import{c as a,Q as d,j as r,m as l}from"./chunks/framework.B2dUnTNU.js";const b=JSON.parse('{"title":"畜牧与狩猎","description":"","frontmatter":{},"headers":[],"relativePath":"b42/animals.md","filePath":"b42/animals.md","lastUpdated":1779624442000}'),e={name:"b42/animals.md"};function s(n,t,o,i,h,c){return d(),r("div",null,[...t[0]||(t[0]=[l(`<h1 id="畜牧与狩猎" tabindex="-1">畜牧与狩猎 <a class="header-anchor" href="#畜牧与狩猎" aria-label="Permalink to &quot;畜牧与狩猎&quot;">​</a></h1><p>B42 首次引入了<strong>活物</strong>——Knox County 不再是只有你一个活人了。动物系统包含<strong>驯养</strong>和<strong>狩猎</strong>两条独立的玩法线，是 B42 &quot;自给自足&quot;理念的核心支柱。</p><div class="tip custom-block"><p class="custom-block-title">B41 玩家注意</p><p>动物是 B42 的<strong>完全新系统</strong>，B41 中没有任何对应的内容。这也被称为&quot;僵尸毁灭工程的第一个 NPC 系统&quot;。</p></div><hr><h2 id="动物总览" tabindex="-1">动物总览 <a class="header-anchor" href="#动物总览" aria-label="Permalink to &quot;动物总览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>动物</th><th>类型</th><th>位置</th><th>产出</th><th>特殊说明</th></tr></thead><tbody><tr><td>🐄 <strong>牛</strong></td><td>家畜</td><td>农场/田野</td><td>牛奶、牛肉、皮革</td><td>可再生奶源，需日常喂养</td></tr><tr><td>🐖 <strong>猪</strong></td><td>家畜</td><td>农场/猪圈</td><td>猪肉、猪皮</td><td>最省饲料——可吃剩菜垃圾</td></tr><tr><td>🐑 <strong>羊</strong></td><td>家畜</td><td>农场</td><td>羊毛、羊肉</td><td>羊毛可用于纺织和护甲</td></tr><tr><td>🐔 <strong>鸡</strong></td><td>家畜</td><td>农场/后院</td><td>鸡蛋、鸡肉</td><td>每日产蛋+吃害虫，散养最佳</td></tr><tr><td>🦌 <strong>鹿</strong></td><td>野生</td><td>森林</td><td>鹿肉、鹿皮、鹿角</td><td>有固定迁徙路线，胆怯</td></tr><tr><td>🐇 <strong>兔</strong></td><td>野生</td><td>田野/森林</td><td>兔肉、兔皮</td><td>小型猎物，肉眼可见可捕捉</td></tr><tr><td>🦊 <strong>狐狸</strong></td><td>野生</td><td>森林/田野</td><td>—</td><td>会潜入圈栏吃幼崽</td></tr><tr><td>🐀 <strong>鼠</strong></td><td>野生</td><td>地窖/旧房</td><td>鼠肉</td><td>紧急食物，可能有心情惩罚</td></tr></tbody></table><hr><h2 id="驯养系统" tabindex="-1">驯养系统 <a class="header-anchor" href="#驯养系统" aria-label="Permalink to &quot;驯养系统&quot;">​</a></h2><h3 id="如何获取家畜" tabindex="-1">如何获取家畜 <a class="header-anchor" href="#如何获取家畜" aria-label="Permalink to &quot;如何获取家畜&quot;">​</a></h3><ol><li>找到农场或田野中的动物</li><li>用绳子或诱饵将其引导至你的基地</li><li>搭建围栏/圈栏（木工或石工制作）</li><li>使用拖车运输大型动物</li></ol><h3 id="日常管理" tabindex="-1">日常管理 <a class="header-anchor" href="#日常管理" aria-label="Permalink to &quot;日常管理&quot;">​</a></h3><table tabindex="0"><thead><tr><th>任务</th><th>频率</th><th>说明</th></tr></thead><tbody><tr><td>喂食</td><td>每日</td><td>不同动物需要不同饲料，猪可吃残羹</td></tr><tr><td>收集产物</td><td>每日</td><td>鸡蛋、牛奶每日可收；羊毛定期收割</td></tr><tr><td>清洁围栏</td><td>定期</td><td>防止疾病</td></tr><tr><td>防狐狸</td><td>持续性</td><td>狐狸会偷幼崽，需加固围栏或设陷阱</td></tr></tbody></table><h3 id="产品链" tabindex="-1">产品链 <a class="header-anchor" href="#产品链" aria-label="Permalink to &quot;产品链&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>家畜 ──→ 肉（直接食用或烟熏保存）</span></span>
<span class="line"><span>    ├── 皮革 ──→ 护甲、腰带、枪套</span></span>
<span class="line"><span>    ├── 骨头 ──→ 针、鱼钩、鱼陷阱、骨粉肥料</span></span>
<span class="line"><span>    ├── 羊毛 ──→ 纺线 ──→ 冬衣</span></span>
<span class="line"><span>    ├── 粪便 ──→ 作物肥料（闭合农耕循环）</span></span>
<span class="line"><span>    ├── 牛奶 ──→ 饮用或制奶酪（需开发中功能）</span></span>
<span class="line"><span>    └── 鸡蛋 ──→ 食用或烹饪（高效烹饪经验）</span></span></code></pre></div><hr><h2 id="狩猎系统" tabindex="-1">狩猎系统 <a class="header-anchor" href="#狩猎系统" aria-label="Permalink to &quot;狩猎系统&quot;">​</a></h2><h3 id="追踪技能" tabindex="-1">追踪技能 <a class="header-anchor" href="#追踪技能" aria-label="Permalink to &quot;追踪技能&quot;">​</a></h3><p>B42 新增技能——通过追踪脚印、粪便、断枝来定位猎物：</p><ul><li>鹿沿固定迁徙路线移动，找到路线就能反复狩猎</li><li>枪声和雷声会惊吓动物，暂时压制其活动</li><li>弓是理想的无声狩猎武器（弓箭系统推迟开发中）</li><li>响亮的枪声可以用来故意驱赶动物离开某个区域</li></ul><h3 id="狩猎技巧" tabindex="-1">狩猎技巧 <a class="header-anchor" href="#狩猎技巧" aria-label="Permalink to &quot;狩猎技巧&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">追踪技巧</p><ul><li>雨后泥土上更容易看到新鲜足迹</li><li>顺着粪便的&quot;新鲜度&quot;判断猎物离你有多远</li><li>在林区边缘比密林深处更容易发现鹿</li></ul></div><h3 id="野生动物产品" tabindex="-1">野生动物产品 <a class="header-anchor" href="#野生动物产品" aria-label="Permalink to &quot;野生动物产品&quot;">​</a></h3><table tabindex="0"><thead><tr><th>产物</th><th>来源</th><th>用途</th></tr></thead><tbody><tr><td>鹿肉</td><td>鹿</td><td>高级肉食</td></tr><tr><td>鹿皮</td><td>鹿</td><td>优质皮革</td></tr><tr><td>鹿角</td><td>鹿</td><td>制作工具手柄、装饰</td></tr><tr><td>兔皮</td><td>兔</td><td>小型皮革</td></tr><tr><td>兔肉</td><td>兔</td><td>肉食</td></tr></tbody></table><hr><h2 id="⚠️-重要机制" tabindex="-1">⚠️ 重要机制 <a class="header-anchor" href="#⚠️-重要机制" aria-label="Permalink to &quot;⚠️ 重要机制&quot;">​</a></h2><h3 id="僵尸无视动物" tabindex="-1">僵尸无视动物 <a class="header-anchor" href="#僵尸无视动物" aria-label="Permalink to &quot;僵尸无视动物&quot;">​</a></h3><p>好消息：僵尸不会攻击你的牲畜。坏消息：动物也不会帮你引开僵尸。</p><h3 id="但动物怕噪音" tabindex="-1">但动物怕噪音 <a class="header-anchor" href="#但动物怕噪音" aria-label="Permalink to &quot;但动物怕噪音&quot;">​</a></h3><ul><li>枪声 → 动物逃跑，暂时不活动</li><li>雷暴 → 同上</li><li>僵尸砸门声 → 不会吓到动物</li></ul><h3 id="动物不会生小崽-当前版本" tabindex="-1">动物不会生小崽（当前版本） <a class="header-anchor" href="#动物不会生小崽-当前版本" aria-label="Permalink to &quot;动物不会生小崽（当前版本）&quot;">​</a></h3><p>繁殖机制尚未完全实装——但幼崽模型（小鹿、羊羔）已经在游戏中出现，暗示未来会有。目前需要通过野外不断寻找新动物来补充。</p><hr><h2 id="推荐开局路线" tabindex="-1">推荐开局路线 <a class="header-anchor" href="#推荐开局路线" aria-label="Permalink to &quot;推荐开局路线&quot;">​</a></h2><ol><li><strong>早期</strong>：养鸡——最省心的动物，每日鸡蛋提供稳定食物和烹饪经验</li><li><strong>中期</strong>：加养猪——吃残羹不费饲料，提供大量肉和皮</li><li><strong>后期</strong>：养牛/羊——终极食物/资源自给</li><li><strong>与农耕联动</strong>：动物粪便当肥料，种出来的次品喂猪，形成闭环</li></ol>`,34)])])}const u=a(e,[["render",s]]);export{b as __pageData,u as default};
